import{_ as e,a,o as r,ai as o}from"./chunks/framework.BbOtTPsL.js";const m=JSON.parse('{"title":"Data Transfer Imports","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/settings/data-transfer-imports/overview.md","filePath":"api/graphql-api/admin/settings/data-transfer-imports/overview.md","lastUpdated":1782473079000}'),d={name:"api/graphql-api/admin/settings/data-transfer-imports/overview.md"};function i(n,t,s,c,l,h){return r(),a("div",null,t[0]||(t[0]=[o('<h1 id="data-transfer-imports" tabindex="-1">Data Transfer Imports <a class="header-anchor" href="#data-transfer-imports" aria-label="Permalink to &quot;Data Transfer Imports&quot;">​</a></h1><p>The Data Transfer Imports menu bulk-imports records into the store from a CSV / XLSX / XML file — products, customers, tax rates, and any other entity your store exposes as an importer. It mirrors the admin <strong>Settings → Data Transfer → Imports</strong> screen.</p><p>Each import is a job: an uploaded file, the entity it targets (<code>code</code>), whether it adds or removes rows (<code>action</code>), and a <code>state</code> that tracks how far it has run.</p><h2 id="the-import-lifecycle" tabindex="-1">The import lifecycle <a class="header-anchor" href="#the-import-lifecycle" aria-label="Permalink to &quot;The import lifecycle&quot;">​</a></h2><p>A client drives an import through a fixed sequence of stages. Each stage is a separate call so you can validate, watch progress, and abort between steps.</p><table tabindex="0"><thead><tr><th>Step</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Create</strong></td><td>Upload the source file and choose the entity + options. <strong>REST only</strong> — see below.</td></tr><tr><td><strong>Validate</strong></td><td>Check the file&#39;s columns and rows without importing anything. Surfaces <code>errors[]</code> and the <code>isValid</code> flag.</td></tr><tr><td><strong>Start</strong></td><td>Process the next batch of rows. Call repeatedly until no batches remain.</td></tr><tr><td><strong>Link</strong></td><td>Post-process stage — resolves relationships between the imported records.</td></tr><tr><td><strong>Index</strong></td><td>Final stage — makes the imported records searchable and visible on the storefront.</td></tr><tr><td><strong>Stats</strong></td><td>Poll progress at any point without advancing the job — drives a progress bar.</td></tr><tr><td><strong>Cancel</strong></td><td>Abort a <code>pending</code> or <code>processing</code> job.</td></tr></tbody></table><p>Poll <a href="./stats.html">stats</a> between <a href="./start.html">start</a> / <a href="./link.html">link</a> / <a href="./">index</a> to know when each stage has finished (<code>remaining: 0</code>).</p><h2 id="field-meanings" tabindex="-1">Field meanings <a class="header-anchor" href="#field-meanings" aria-label="Permalink to &quot;Field meanings&quot;">​</a></h2><ul><li><code>code</code> — the entity being imported (<code>products</code>, <code>customers</code>, <code>tax_rates</code>, …).</li><li><code>action</code> — <code>append</code> (insert/update rows) or <code>delete</code> (remove rows).</li><li><code>state</code> — lifecycle position: <code>pending</code>, <code>validated</code>, <code>processing</code>, <code>processed</code>, <code>linked</code>, <code>indexed</code>, <code>completed</code>, <code>cancelled</code>, …</li><li><code>validationStrategy</code> / <code>allowedErrors</code> — <code>stop-on-errors</code> or <code>skip-errors</code>, and the error budget for the latter.</li><li><code>processedRowsCount</code> / <code>invalidRowsCount</code> / <code>errorsCount</code> — progress and validation counters.</li><li><code>errors</code> — the list of validation messages (null on listing rows; fetch the detail to read it).</li><li><code>summary</code> — created/updated/deleted counts after a run (null until the run completes).</li><li><code>filePath</code> / <code>errorFilePath</code> / <code>imagesDirectoryPath</code> — storage paths. The source file and error report are <strong>downloadable over REST only</strong>.</li></ul><h2 id="rest-only-operations" tabindex="-1">REST-only operations <a class="header-anchor" href="#rest-only-operations" aria-label="Permalink to &quot;REST-only operations&quot;">​</a></h2><ul><li><strong>Create</strong> requires a multipart file upload, which a JSON GraphQL request cannot carry — the GraphQL <code>create</code> mutation always rejects with a pointer to REST.</li><li><strong>File downloads</strong> (source file, error report, sample template) are binary and have no GraphQL counterpart.</li></ul><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="./list.html">List imports</a></td><td><code>adminSettingsDataTransferImports</code> query</td></tr><tr><td><a href="./detail.html">Get a single import</a></td><td><code>adminSettingsDataTransferImport(id:)</code> query</td></tr><tr><td><a href="./create.html">Create import</a></td><td>REST only (multipart upload)</td></tr><tr><td><a href="./validate.html">Validate import</a></td><td><code>validateAdminSettingsDataTransferImportValidate</code> mutation</td></tr><tr><td><a href="./start.html">Start import</a></td><td><code>startAdminSettingsDataTransferImportStart</code> mutation</td></tr><tr><td><a href="./link.html">Link import</a></td><td><code>linkAdminSettingsDataTransferImportLink</code> mutation</td></tr><tr><td><a href="./">Index import</a></td><td><code>indexAdminSettingsDataTransferImportIndex</code> mutation</td></tr><tr><td><a href="./stats.html">Import stats</a></td><td><code>adminSettingsDataTransferImportStats(id:)</code> query</td></tr><tr><td><a href="./delete.html">Delete import</a></td><td><code>deleteAdminSettingsDataTransferImport</code> mutation</td></tr><tr><td><a href="./cancel.html">Cancel import</a></td><td><code>cancelAdminSettingsDataTransferImportCancel</code> mutation</td></tr></tbody></table><p>Permissions: <code>settings.data_transfer.imports.create</code> / <code>.edit</code> / <code>.delete</code> / <code>.view</code>.</p><p>All operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',15)]))}const u=e(d,[["render",i]]);export{m as __pageData,u as default};
